// Golden test: the Go port must agree with the TypeScript that is currently
// running in production, to the paisa.
//
// testdata/golden.json is generated by bundling the real frontend engine and
// running it over the real seed profile:
//
//	npx esbuild internal/engine/testdata/golden.ts --bundle --platform=node \
//	    --format=esm --outfile=/tmp/golden.mjs && node /tmp/golden.mjs \
//	    > internal/engine/testdata/golden.json
//
// This is what makes the port safe to ship. A rewrite that "looks right" is
// how a finance app quietly starts showing different numbers on two screens;
// this test makes that a build failure instead of a support ticket.

type goldenFile struct {
	Runway struct {
		EssentialBurn     int64   `json:"essentialBurn"`
		DiscretionaryBurn int64   `json:"discretionaryBurn"`
		DebtService       int64   `json:"debtService"`
		TotalBurn         int64   `json:"totalBurn"`
		LiquidToday       int64   `json:"liquidToday"`
		Liquid1y          int64   `json:"liquid1y"`
		Locked            int64   `json:"locked"`
		Months            float64 `json:"months"`
		Target            float64 `json:"target"`
		Gap               int64   `json:"gap"`
		Status            string  `json:"status"`
	} `json:"runway"`
	Score struct {
		Total          int     `json:"total"`
		NetWorth       int64   `json:"netWorth"`
		FINumber       int64   `json:"fiNumber"`
		FIProgress     float64 `json:"fiProgress"`
		YearsToFreedom float64 `json:"yearsToFreedom"`
		Surplus        int64   `json:"surplus"`
		SavingsRate    float64 `json:"savingsRate"`
		Pillars        []struct {
			Key   string  `json:"key"`
			Score float64 `json:"score"`
			Max   float64 `json:"max"`
			State string  `json:"state"`
		} `json:"pillars"`
	} `json:"score"`
}

// seedProfile mirrors src/domain/seed.ts exactly, converted to paise.
