func loadGolden(t *testing.T) goldenFile {
	t.Helper()
	raw, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatalf("read golden: %v (regenerate it - see the comment above)", err)
	}
	var g goldenFile
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("parse golden: %v", err)
	}
	return g
}

// Two paise of slack. The TypeScript accumulates in float rupees, so its
// totals carry a little representation error; Go is exact. Anything larger
// than this is a genuine logic divergence, not float noise.
const tolerancePaise = int64(2)

func assertPaise(t *testing.T, name string, got, want int64) {
	t.Helper()
	diff := got - want
	if diff < 0 {
		diff = -diff
	}
	if diff > tolerancePaise {
		t.Errorf("%s: got %d paise, want %d (diff %d)", name, got, want, diff)
	}
}

func assertFloat(t *testing.T, name string, got, want, tol float64) {
	t.Helper()
	if math.Abs(got-want) > tol {
		t.Errorf("%s: got %v, want %v (diff %v)", name, got, want, math.Abs(got-want))
	}
}

func TestRunwayMatchesTypeScript(t *testing.T) {
	g := loadGolden(t)
	got := ComputeRunway(seedProfile(), time.Now())

	assertPaise(t, "essentialBurn", got.EssentialBurn, g.Runway.EssentialBurn)
	assertPaise(t, "discretionaryBurn", got.DiscretionaryBurn, g.Runway.DiscretionaryBurn)
	assertPaise(t, "debtService", got.DebtService, g.Runway.DebtService)
	assertPaise(t, "totalBurn", got.TotalBurn, g.Runway.TotalBurn)
	assertPaise(t, "liquidToday", got.LiquidToday, g.Runway.LiquidToday)
	assertPaise(t, "liquid1y", got.Liquid1y, g.Runway.Liquid1y)
	assertPaise(t, "locked", got.Locked, g.Runway.Locked)
	assertPaise(t, "gap", got.Gap, g.Runway.Gap)

	assertFloat(t, "months", got.Months, g.Runway.Months, 1e-6)
	assertFloat(t, "target", got.Target, g.Runway.Target, 1e-9)

	if string(got.Status) != g.Runway.Status {
		t.Errorf("status: got %q, want %q", got.Status, g.Runway.Status)
	}
}

func TestFreedomScoreMatchesTypeScript(t *testing.T) {
	g := loadGolden(t)
	p := seedProfile()
	got := ComputeFreedomScore(p, ComputeRunway(p, time.Now()))

	if got.Total != g.Score.Total {
		t.Errorf("total: got %d, want %d", got.Total, g.Score.Total)
	}
	assertPaise(t, "netWorth", got.NetWorth, g.Score.NetWorth)
	assertPaise(t, "fiNumber", got.FINumber, g.Score.FINumber)
	assertPaise(t, "surplus", got.Surplus, g.Score.Surplus)

	assertFloat(t, "fiProgress", got.FIProgress, g.Score.FIProgress, 1e-9)
	assertFloat(t, "savingsRate", got.SavingsRate, g.Score.SavingsRate, 1e-9)
	assertFloat(t, "yearsToFreedom", got.YearsToFreedom, g.Score.YearsToFreedom, 1e-9)

	if len(got.Pillars) != len(g.Score.Pillars) {
		t.Fatalf("pillars: got %d, want %d", len(got.Pillars), len(g.Score.Pillars))
	}
	for i, want := range g.Score.Pillars {
		have := got.Pillars[i]
		if have.Key != want.Key {
			t.Errorf("pillar %d key: got %q, want %q", i, have.Key, want.Key)
		}
		assertFloat(t, "pillar "+want.Key+" score", have.Score, want.Score, 1e-9)
		if have.State != want.State {
			t.Errorf("pillar %s state: got %q, want %q", want.Key, have.State, want.State)
		}
	}
}

// A guard against the failure mode the whole paise convention exists to
// prevent: adding a rupee amount a thousand times should land exactly, and
// in float64 it does not.
func TestPaiseArithmeticIsExact(t *testing.T) {
	var totalPaise int64
	totalFloat := 0.0
	for i := 0; i < 1000; i++ {
		totalPaise += 10 // 0.10
		totalFloat += 0.10
	}
	if totalPaise != 10000 {
		t.Fatalf("integer paise drifted: %d", totalPaise)
	}
	if totalFloat == 100.0 {
		t.Skip("this float64 happened to land exactly; the point still stands")
	}
	t.Logf("float64 drift after 1000 additions of 0.10: %.20f vs 100.0", totalFloat)
}
